# src/gridiron_edge/market/edge_validation.py

"""Whether raw model-versus-market expected value may be shown as an edge (``DECISIONS.md`` D85)."""

from __future__ import annotations

from typing import Final

#: Raw model EV treats the model's probability or total as the truth. On walk-forward backfills
#: against the closing lines the model's disagreements did not predict outcomes
#: (``docs/reports/market-agreement.md``, regenerated by ``gridiron evaluate market-agreement``),
#: so edges, recommendations and stakes derived from it are withheld. Set this to ``True`` only
#: together with a DECISIONS.md entry and a report whose rule is passed.
RAW_MODEL_EDGES_VALIDATED: Final[bool] = False

REPORT_PATH: Final[str] = "docs/reports/market-agreement.md"
EXPLANATION: Final[str] = (
    "Model edges are withheld: where the model disagreed with the closing market, outcomes "
    f"followed the market (see {REPORT_PATH}), so its expected value is not an edge."
)
